using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
namespace SlopStudio {
 public sealed class EffectKnob:ScaledCanvas {
  public EffectParameter Parameter;public double Value;public bool Exponential;public event Action<double> Changed;private double _initial;private int _start;private bool _drag;
  public EffectKnob(){DoubleBuffered=true;Cursor=Cursors.Hand;BackColor=Color.FromArgb(42,46,51);}
  private double Normal{get{double n=Parameter.Key.StartsWith("Frequency")?Math.Log(Value/Parameter.Min)/Math.Log(Parameter.Max/Parameter.Min):(Value-Parameter.Min)/(Parameter.Max-Parameter.Min);return Exponential?Math.Sqrt(Math.Max(0,n)):n;}}
  protected override void OnPaint(PaintEventArgs e){PreparePaint(e);e.Graphics.Clear(BackColor);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;int size=Math.Min(56,Math.Min(Width-10,Height-8));if(size<10)return;var rect=new Rectangle((Width-size)/2,(Height-size)/2,size,size);using(var p=new Pen(Color.FromArgb(19,22,25),4))e.Graphics.DrawArc(p,rect,135,270);using(var p=new Pen(Color.FromArgb(121,182,222),3))e.Graphics.DrawArc(p,rect,135,(float)(270*Math.Max(0,Math.Min(1,Normal))));rect.Inflate(-6,-6);using(var brush=new LinearGradientBrush(rect,Color.FromArgb(166,171,175),Color.FromArgb(73,79,85),70))e.Graphics.FillEllipse(brush,rect);using(var p=new Pen(Color.FromArgb(35,39,44),1.5f))e.Graphics.DrawEllipse(p,rect);double angle=(135+270*Normal)*Math.PI/180;float cx=rect.X+rect.Width/2f,cy=rect.Y+rect.Height/2f;using(var p=new Pen(Color.FromArgb(219,235,245),2))e.Graphics.DrawLine(p,cx+(float)Math.Cos(angle)*rect.Width*.24f,cy+(float)Math.Sin(angle)*rect.Height*.24f,cx+(float)Math.Cos(angle)*rect.Width*.43f,cy+(float)Math.Sin(angle)*rect.Height*.43f);}
  private void Set(double normal){normal=Math.Max(0,Math.Min(1,normal));double scaled=Exponential?normal*normal:normal;Value=Parameter.Key.StartsWith("Frequency")?Parameter.Min*Math.Pow(Parameter.Max/Parameter.Min,scaled):Parameter.Min+(Parameter.Max-Parameter.Min)*scaled;if(Parameter.Key=="Mode"||Parameter.Key=="Input")Value=Math.Round(Value);Invalidate();if(Changed!=null)Changed(Value);}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left){Focus();_drag=true;_start=PointToScreen(e.Location).Y;_initial=Normal;Capture=true;}}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(_drag)Set(_initial+(_start-PointToScreen(e.Location).Y)/((ModifierKeys&Keys.Shift)!=0?1200.0:200));}
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);_drag=false;Capture=false;}
  protected override void OnMouseWheel(MouseEventArgs e){base.OnMouseWheel(e);Set(Normal+Math.Sign(e.Delta)*.01);}
  protected override void OnMouseDoubleClick(MouseEventArgs e){base.OnMouseDoubleClick(e);Value=Parameter.Default;Set(Normal);}
 }
 public sealed class EffectDisplay:ScaledCanvas {
  public StockEffectSlot Slot;public Func<StockEffectProcessor> Processor;public EffectDisplay(){DoubleBuffered=true;BackColor=Color.FromArgb(20,24,29);}
  private static string Db(float p){return p<.000001?"−∞":(20*Math.Log10(p)).ToString("0.0");}
  protected override void OnPaint(PaintEventArgs e){PreparePaint(e);var g=e.Graphics;g.Clear(BackColor);g.SmoothingMode=SmoothingMode.AntiAlias;Rectangle area=new Rectangle(40,18,Math.Max(1,Width-72),Math.Max(1,Height-45));using(var pen=new Pen(Color.FromArgb(43,51,60))){for(int i=0;i<=8;i++)g.DrawLine(pen,area.Left+i*area.Width/8,area.Top,area.Left+i*area.Width/8,area.Bottom);for(int i=0;i<=4;i++)g.DrawLine(pen,area.Left,area.Top+i*area.Height/4,area.Right,area.Top+i*area.Height/4);}var points=new List<PointF>();bool duck=Slot.Kind=="EDM Ducker";for(int x=0;x<=area.Width;x++){double t=x/(double)area.Width,gain=t;if(duck){int mode=(int)Slot.Value("Mode",0);double amount=mode==0?Math.Pow(1-t,2):Math.Exp(-t*Slot.Value("Period",1)*.5/(Slot.Value("Release",220)*.001));gain=1-Slot.Value("Depth",80)/100*amount;}else if(Slot.Kind=="Compressor"){double db=-60+t*60,threshold=Slot.Value("Threshold",-18),outDb=db>threshold?threshold+(db-threshold)/Slot.Value("Ratio",4):db;gain=(outDb+60)/60;}else if(Slot.Kind=="Saturator")gain=(Math.Tanh((t*2-1)*Math.Pow(10,Slot.Value("Drive",6)/20))+1)/2;else if(Slot.Kind=="Limiter")gain=Math.Min(t,Math.Pow(10,Slot.Value("Ceiling",-.5)/20));points.Add(new PointF(area.X+x,(float)(area.Bottom-gain*area.Height)));}if(points.Count>1){using(var p=new GraphicsPath()){p.AddLines(points.ToArray());p.AddLine(points[points.Count-1],new PointF(area.Right,area.Bottom));p.AddLine(new PointF(area.Right,area.Bottom),new PointF(area.Left,area.Bottom));p.CloseFigure();using(var b=new SolidBrush(Color.FromArgb(28,82,173,229)))g.FillPath(b,p);}using(var p=new Pen(duck?Color.FromArgb(177,146,238):Color.FromArgb(94,185,231),2.3f))g.DrawLines(p,points.ToArray());}var processor=Processor();if(processor!=null){string text="IN  "+Db(processor.InputPeak)+" dB     OUT  "+Db(processor.OutputPeak)+" dB     GR  "+processor.Reduction.ToString("0.0")+" dB";StudioDraw.Label(g,text,Font,new Rectangle(area.X,Height-24,area.Width,20),Color.FromArgb(183,204,221),TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter);}StudioDraw.Label(g,duck?UiText.Translate("ENVELOPE")+"  /  "+UiText.Translate(new[]{"AUTO","MIDI","AUDIO"}[(int)Slot.Value("Mode",0)]):UiText.Translate("TRANSFER"),Font,new Rectangle(area.X+8,area.Y+5,220,18),Color.Silver,TextFormatFlags.VerticalCenter);}
 }
}
